local function curry2(fn)
  return function(a)
    return function(b)
      return fn(a, b)
    end
  end
end

local add = curry2(function(a, b) return a + b end)
print(add(2)(3))

local add10 = add(10)
print(add10(5), add10(-1))

local function curry3(fn)
  return function(a)
    return function(b)
      return function(c)
        return fn(a, b, c)
      end
    end
  end
end

local format3 = curry3(string.format)
print(format3("%s=%d")("count")(7))

